# lib/01_cryptocurrencies.rb

def analyze_cryptocurrencies(names, prices)
    # Associer chaque devise à son montant
    my_hash = names.zip(prices).to_h
  
    # La ou les crypto qui ont la plus grosse valeur
    max_value_crypto = my_hash.max_by { |_, value| value }
    puts "La crypto avec la plus grosse valeur est #{max_value_crypto}."
  
    # La ou les crypto qui ont la plus petite valeur
    min_value_crypto = my_hash.min_by { |_, value| value }
    puts "La crypto avec la plus petite valeur est #{min_value_crypto}."
  
    # Les devises dont le cours est inférieur à 6000
    cryptos_under_6000 = my_hash.select { |_, value| value < 6000 }
    puts "Les devises dont le cours est inférieur à 6000 sont : #{cryptos_under_6000}."
  
    # La devise la plus chère parmi celles dont le cours est inférieur à 6000
    most_expensive_under_6000 = cryptos_under_6000.max_by { |_, value| value }
    puts "La devise la plus chère parmi celles dont le cours est inférieur à 6000 est #{most_expensive_under_6000}."
  end
  
